"""Generate browser schemas from the authoritative service models; --check prevents drift."""
import json
from pathlib import Path
import sys
root = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(root / 'apps/horizon'))
from horizon.models import Equipment
from horizon.exchange import PlanExchange
schemas = {'equipment': Equipment.model_json_schema(), 'plan': PlanExchange.model_json_schema()}
outputs = {
    root / 'packages/contracts/schemas.json': json.dumps(schemas, indent=2) + '\n',
    root / 'source/assets/tools/prismo-contracts.js':
        '// Generated by scripts/generate-contracts.py. Edit packages/contracts/exchange.js.\n'
        + 'globalThis.PrismoSchemas = ' + json.dumps(schemas, separators=(',', ':')) + ';\n'
        + (root / 'packages/contracts/exchange.js').read_text(),
}
for path, value in outputs.items():
    if '--check' in sys.argv:
        if not path.exists() or path.read_text() != value:
            raise SystemExit(f'Stale generated contract: {path.relative_to(root)}')
    else:
        path.write_text(value)
